input.command:
mkdir -p notes && cat > notes/PRC-501.md <<'EOF'
# PRC-501
- 症状: `bin/price 999` が 900 を返す。期待は 899（10% 引き・切り捨て）。
- 原因: ee322d6 "tidy up rounding" で `($1*90+99)/100`（切り上げ）に変更された。
- 同じ式が bin/quote と lib/invoice.sh にもあり、同じ誤りを持つ。3 か所とも `$1 * 90 / 100` に戻す。
- テスト: tests/price_test.sh に 999 のケースを追加。quote / invoice も確認する。
EOF
cat > tests/price_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash -c 'source lib/invoice.sh 999' 2>/dev/null || bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
EOF
ls lib; bash scripts/verify.sh
